const today = new Date();

// Check if s exists and has signal_type to avoid errors
const s = $json;
if (!s || !s.signal_type) {
  return [];
}

const price = s.price_at_signal || 0;
const isBuy = s.signal_type.includes('BUY');

// Analyst formatting
let analystTape = "No recent analyst data.";
const analysts = s.analysts || [];

if (analysts.length > 0) {
  analystTape = analysts.map(a => {
    const callDate = new Date(a.date);
    const diffDays = Math.floor((today - callDate) / (1000 * 60 * 60 * 24));
    const ago = diffDays === 0 ? 'today' : `${diffDays} days ago`;
    const upside = (a.target && price > 0) ? (((a.target - price) / price) * 100).toFixed(1) : 'N/A';
    const upsideStr = upside !== 'N/A' ? ` (+${upside}%)` : '';
    return `• **${a.firm}** (${ago}): ${a.action} → **$${a.target}**${upsideStr}`;
  }).join('\n');
}

// Consensus formatting
const conUpside = (s.consensus_target && price > 0) ? (((s.consensus_target - price) / price) * 100).toFixed(1) : 'N/A';
const consensusStr = s.consensus_target ? `**$${s.consensus_target.toFixed(2)}**` + (conUpside !== 'N/A' ? ` (+${conUpside}% upside)` : '') : "N/A";

return {
  ...s,
  isBuy,
  color: isBuy ? 3066993 : 15158332,
  emoji: isBuy ? '🟢' : '🔴',
  analystTape,
  consensusStr,
  historySection: (isBuy && s.performance_history) ? s.performance_history : null
};

